117: /** 极简 CORS + JSON 响应。 */
118: function sendJson(res, status, obj) {
119:   const body = JSON.stringify(obj);
120:   res.writeHead(status, {
121:     "content-type": "application/json; charset=utf-8",
122:     "cache-control": "no-store",
123:     "access-control-allow-origin": "*",
124:     "access-control-allow-methods": "GET, OPTIONS",
125:     "access-control-allow-headers": "content-type",
126:   });
127:   res.end(body);
128: }
129: 
130: export function apply(ctx, raw) {
131:   const config = normalizeConfig(raw);
132:   ctx.logger?.info?.(`[dsh-token-models] loaded; orchestrator usage endpoint ready (dir=${config.sessionsDir})`);
133: 
134:   // 注册 HTTP 路由（webServer 已在 inject 中声明，正常必可用）。
135:   const webServer = ctx.webServer ?? ctx.get?.("webServer");
136:   if (webServer && typeof webServer.register === "function") {
137:     const path = "/api/token-models/orchestrator-usage";
138:     const dispose = webServer.register({
139:       kind: "exact",
140:       path,
141:       handler: async (req, res) => {
142:         try {
143:           if (req.method === "OPTIONS") {
144:             sendJson(res, 204, {});
145:             return;
146:           }
147:           if (req.method !== "GET") {
148:             sendJson(res, 405, { ok: false, error: "method not allowed" });
149:             return;
150:           }
151:           const url = new URL(req.url ?? path, "http://x");
152:           const sessionId = url.searchParams.get("session_id") ?? undefined;
153:           const result = aggregate(config, sessionId);
154:           sendJson(res, result.ok ? 200 : 500, result);
155:         } catch (e) {
156:           sendJson(res, 500, { ok: false, error: String(e?.message ?? e) });
157:         }
158:       },
159:     });
160:     ctx.effect?.(() => dispose, "token-models: orchestrator-usage route");
161:     ctx.logger?.info?.(`[dsh-token-models] route registered: GET ${path}`);
162:   } else {
163:     ctx.logger?.warn?.(`[dsh-token-models] webServer service not available; orchestrator-usage endpoint NOT registered`);
164:   }
165: }
166: 
